// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Liveness probe
	// (GET /healthz)
	UserServiceHealth(ctx context.Context, request UserServiceHealthRequestObject) (UserServiceHealthResponseObject, error)
	// Read the audit log (no appointment contents)
	// (GET /v1/admin/audit-log)
	AdminListAuditLog(ctx context.Context, request AdminListAuditLogRequestObject) (AdminListAuditLogResponseObject, error)
	// Read the retention periods A to E
	// (GET /v1/admin/retention)
	AdminGetRetention(ctx context.Context, request AdminGetRetentionRequestObject) (AdminGetRetentionResponseObject, error)
	// Set the retention periods A to E
	// (PUT /v1/admin/retention)
	AdminSetRetention(ctx context.Context, request AdminSetRetentionRequestObject) (AdminSetRetentionResponseObject, error)
	// List users (no appointment data)
	// (GET /v1/admin/users)
	AdminListUsers(ctx context.Context, request AdminListUsersRequestObject) (AdminListUsersResponseObject, error)
	// Create a user (UF-10)
	// (POST /v1/admin/users)
	AdminCreateUser(ctx context.Context, request AdminCreateUserRequestObject) (AdminCreateUserResponseObject, error)
	// Delete a user account (UF-13)
	// (DELETE /v1/admin/users/{userId})
	AdminDeleteUser(ctx context.Context, request AdminDeleteUserRequestObject) (AdminDeleteUserResponseObject, error)
	// Show a user
	// (GET /v1/admin/users/{userId})
	AdminGetUser(ctx context.Context, request AdminGetUserRequestObject) (AdminGetUserResponseObject, error)
	// Send a password reset link (UF-10)
	// (POST /v1/admin/users/{userId}/password-reset)
	AdminResetPassword(ctx context.Context, request AdminResetPasswordRequestObject) (AdminResetPasswordResponseObject, error)
	// Replace the roles of a user (UF-10)
	// (PUT /v1/admin/users/{userId}/roles)
	AdminSetRoles(ctx context.Context, request AdminSetRolesRequestObject) (AdminSetRolesResponseObject, error)
	// Unlock a locked account (SR.05, UF-10)
	// (POST /v1/admin/users/{userId}/unlock)
	AdminUnlockUser(ctx context.Context, request AdminUnlockUserRequestObject) (AdminUnlockUserResponseObject, error)
	// Confirm a new e-mail address
	// (POST /v1/auth/email-change/confirm)
	ConfirmEmailChange(ctx context.Context, request ConfirmEmailChangeRequestObject) (ConfirmEmailChangeResponseObject, error)
	// Password step of the login (UF-02)
	// (POST /v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// MFA step of the login (UF-02, UF-03)
	// (POST /v1/auth/login/mfa)
	LoginMfa(ctx context.Context, request LoginMfaRequestObject) (LoginMfaResponseObject, error)
	// Revoke the own token
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Request a password reset link (UF-12)
	// (POST /v1/auth/password/forgot)
	ForgotPassword(ctx context.Context, request ForgotPasswordRequestObject) (ForgotPasswordResponseObject, error)
	// Set a new password with a reset token (UF-10, UF-12)
	// (POST /v1/auth/password/reset)
	ResetPassword(ctx context.Context, request ResetPasswordRequestObject) (ResetPasswordResponseObject, error)
	// Register a patient (UF-01)
	// (POST /v1/auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// Confirm the e-mail address (UF-01)
	// (POST /v1/auth/verify-email)
	VerifyEmail(ctx context.Context, request VerifyEmailRequestObject) (VerifyEmailResponseObject, error)
	// Public signing keys (JWKS)
	// (GET /v1/jwks)
	GetJwks(ctx context.Context, request GetJwksRequestObject) (GetJwksResponseObject, error)
	// Own profile (accepts scope=setup)
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Change own profile data
	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// Delete the own account (UF-13)
	// (POST /v1/me/deletion)
	DeleteOwnAccount(ctx context.Context, request DeleteOwnAccountRequestObject) (DeleteOwnAccountResponseObject, error)
	// Request an e-mail change
	// (POST /v1/me/email)
	RequestEmailChange(ctx context.Context, request RequestEmailChangeRequestObject) (RequestEmailChangeResponseObject, error)
	// Confirm TOTP setup (UF-03, UF-04; accepts scope=setup)
	// (POST /v1/me/mfa/confirm)
	MfaSetupConfirm(ctx context.Context, request MfaSetupConfirmRequestObject) (MfaSetupConfirmResponseObject, error)
	// Remove MFA (UF-04)
	// (POST /v1/me/mfa/disable)
	MfaDisable(ctx context.Context, request MfaDisableRequestObject) (MfaDisableResponseObject, error)
	// Replace the recovery codes (UF-04)
	// (POST /v1/me/mfa/recovery-codes)
	MfaRegenerateRecoveryCodes(ctx context.Context, request MfaRegenerateRecoveryCodesRequestObject) (MfaRegenerateRecoveryCodesResponseObject, error)
	// Start TOTP setup (UF-03, UF-04; accepts scope=setup)
	// (POST /v1/me/mfa/setup)
	MfaSetupStart(ctx context.Context, request MfaSetupStartRequestObject) (MfaSetupStartResponseObject, error)
	// Change own password (accepts scope=setup)
	// (POST /v1/me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

